from typing import List, Optional, Union, Tuple

Number = Union[int, float]

class Token:
    __slots__ = ('type', 'value', 'pos')
    def __init__(self, type: str, value: str, pos: int):
        self.type = type
        self.value = value
        self.pos = pos
    def __repr__(self):
        return f'Token({self.type}, {self.value!r})'

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def peek(self) -> str:
        if self.pos < self.length:
            return self.text[self.pos]
        return '\0'

    def advance(self) -> str:
        ch = self.peek()
        self.pos += 1
        return ch

    def tokenize(self) -> List[Token]:
        tokens = []
        while self.pos < self.length:
            ch = self.peek()
            if ch in ' \t\r\n':
                self.advance()
                continue
            if ch == '#':
                while self.pos < self.length and self.peek() != '\n':
                    self.advance()
                continue
            if ch == ';':
                tokens.append(Token('SEMI', ';', self.pos))
                self.advance()
                continue
            if ch.isdigit() or ch == '.':
                start = self.pos
                has_dot = False
                while self.pos < self.length:
                    c = self.peek()
                    if c.isdigit():
                        self.advance()
                    elif c == '.' and not has_dot:
                        has_dot = True
                        self.advance()
                    else:
                        break
                num_str = self.text[start:self.pos]
                if num_str == '.':
                    raise SyntaxError(f'Syntax error at position {start}')
                if has_dot:
                    value = float(num_str)
                else:
                    value = int(num_str)
                tokens.append(Token('NUMBER', value, start))
                continue
            if ch.isalpha() or ch == '_':
                start = self.pos
                while self.pos < self.length:
                    c = self.peek()
                    if c.isalnum() or c == '_':
                        self.advance()
                    else:
                        break
                name = self.text[start:self.pos]
                if name in ('min', 'max', 'abs'):
                    tokens.append(Token('FUNC', name, start))
                else:
                    tokens.append(Token('NAME', name, start))
                continue
            if ch == '+':
                self.advance()
                if self.peek() == '+':
                    raise SyntaxError(f'Syntax error at position {self.pos-1}')
                tokens.append(Token('PLUS', '+', self.pos-1))
                continue
            if ch == '-':
                self.advance()
                tokens.append(Token('MINUS', '-', self.pos-1))
                continue
            if ch == '*':
                self.advance()
                if self.peek() == '*':
                    self.advance()
                    tokens.append(Token('POWER', '**', self.pos-2))
                else:
                    tokens.append(Token('MUL', '*', self.pos-1))
                continue
            if ch == '/':
                self.advance()
                tokens.append(Token('DIV', '/', self.pos-1))
                continue
            if ch == '%':
                self.advance()
                tokens.append(Token('MOD', '%', self.pos-1))
                continue
            if ch == '=':
                self.advance()
                tokens.append(Token('ASSIGN', '=', self.pos-1))
                continue
            if ch == '(':
                self.advance()
                tokens.append(Token('LPAREN', '(', self.pos-1))
                continue
            if ch == ')':
                self.advance()
                tokens.append(Token('RPAREN', ')', self.pos-1))
                continue
            if ch == ',':
                self.advance()
                tokens.append(Token('COMMA', ',', self.pos-1))
                continue
            raise SyntaxError(f'Syntax error at position {self.pos}')
        tokens.append(Token('EOF', '', self.pos))
        return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.current = tokens[0]

    def advance(self):
        self.pos += 1
        if self.pos < len(self.tokens):
            self.current = self.tokens[self.pos]

    def expect(self, type: str) -> Token:
        if self.current.type != type:
            raise SyntaxError(f'Syntax error at position {self.current.pos}')
        tok = self.current
        self.advance()
        return tok

